'use client';
import React, { useState } from "react";


export default function  Passions(){
    const [hoverIndex,setHoverIndex]=useState(-1);
    const passionItems=[
        {
            id:0,
            title:"Front-End development",
            subTitle:"React,NextJs,Angular,Flutter"
        },
        {
            id:1,
            title:"Back-End developement",
            subTitle:"NodeJS,Express,MongoDb,Python"
        },
        {
            id:2,
            title:"UI/UX",
            subTitle:"Figma, Adobe XD"
        }
    ]
    return(
        <div className="flex flex-col w-[100%]">
            <div className="w-full item">MY SKILLS</div>
            <div className="flex flex-col w-[100%] items-center justify-center">
                <div className="flex w-fit flex-row  items-center border rounded-[20px] justify-center gap-3">
                    {passionItems.map((item,index)=>(
                        <React.Fragment key={index}>
                            <div className={`transition duration-1000 ${hoverIndex === index ? `bg-[#000] text-white `:`text-black bg-white`} cursor-pointer p-2 rounded-[20px]`} onClick={()=>{setHoverIndex(index)}}>
                                {item.title}
                            </div>
                            {index+1 !== passionItems.length &&
                                <span> | </span>
                            }
                        </React.Fragment>
                    ))}
                </div>
                {passionItems.map((item,index)=>(
                    <div className="flex flex-col w-[40%] ml-4 rounded-[20px]" key={index}>
                        <div className="text-2xl">{item.title}</div>
                        <div className="text-large">{item.subTitle}</div>
                    </div>
                ))}
            </div>
        </div>
    )
}
